    {
      "service": "ts-preserve-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Client' AND attr_status_code='Error' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_status_code, count(*), round(quantile_cont(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Client' AND attr_status_code='Error' GROUP BY 1,2,3,4", "claim": "ts-preserve-service has 1497 Error outbound POST client spans in abnormal period, zero in normal, failing in about 1.4 ms."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level='SEVERE' AND message LIKE '%ts-seat-service%' GROUP BY 1,2,3 ORDER BY n DESC LIMIT 3", "claim": "Preserve SEVERE logs show POST to ts-seat-service/seats failing with 'Unexpected end of file' and 'Connection reset'."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='POST /api/v1/seatservice/seats' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_status_code, count(*) FROM normal_traces WHERE service_name='ts-seat-service' AND span_name='POST /api/v1/seatservice/seats' GROUP BY 1,2,3,4", "claim": "Seat's own POST /seats server spans vanish in abnormal period (132 normal, 0 abnormal); the failing requests never reach seat's app."},
        {"kind": "metric", "sql": "SELECT metric, attr_source, attr_destination, round(sum(value),0) total FROM abnormal_metrics_sum WHERE metric LIKE 'hubble%' AND attr_source LIKE '%ts-preserve-service%' AND attr_destination LIKE '%ts-seat-service%' GROUP BY 1,2,3", "claim": "Hubble flows preserve→seat keep flowing with no drop counters, so the cut is at HTTP level, not network loss or partition."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE 'POST /api/v1/preserveservice/preserve%' GROUP BY 1,2,3", "claim": "Dashboard's preserve requests show 80 Error responses at about 5 s p95, versus none in normal."}]}
  ]
}
